{
  "item_id": "PRISMA_2020_3",
  "elements": [
    {
      "element_id": "prisma_2020_3_e1",
      "status": "PRESENT",
      "chunk_id": "text_6",
      "quote": "Unreliable results may be produced when either assumption is unreasonable [3, 24]. NMAs have been described as the highest level of evidence, above PW-MAs, and have huge potential to provide important evidence to inform guidelines [31, 33-37]. ... Limited research has explored the use of NMAs to inform guidelines [38].",
      "reason": "The manuscript describes the current state of knowledge regarding NMA reviews, including their potential benefits and the risks of unreliable results, as well as the limited existing research on their use in guidelines."
    },
    {
      "element_id": "prisma_2020_3_e2",
      "status": "PRESENT",
      "chunk_id": "text_6",
      "quote": "Our article is the first to systematically search for reviews and summarise their citation in guidelines, and to explore the citation of reviews in depth. In this article, we build on prior research by conducting a systematic review of Cochrane Reviews that applied NMA to summarise which reviews were cited in guidelines... We anticipate that our research will highlight the extent of potential research waste, help review authors to maximise the impact of their reviews, aid guidelines developers to improve and increase the use of NMA and PW-MA reviews, and lead to improved collaboration to increase research efficiency.",
      "reason": "The authors explain the importance of their review by highlighting that it is the first to systematically search for and explore the citation of Cochrane NMA reviews in depth, and they outline the anticipated benefits of the research."
    },
    {
      "element_id": "prisma_2020_3_e3",
      "status": "PRESENT",
      "chunk_id": "text_6",
      "quote": "Lunny et al summarised how often NMAs and PW-MAs support recommendations in a sample of 50 guidelines [15]. Our article is the first to systematically search for reviews and summarise their citation in guidelines, and to explore the citation of reviews in depth.",
      "reason": "The authors identify a previous similar review (Lunny et al.) and explain the need for the current review by noting that their work is the first to systematically search for and explore the citation of Cochrane reviews in depth, and by contrasting their findings with the previous work."
    },
    {
      "element_id": "prisma_2020_3_e4",
      "status": "NOT_APPLICABLE",
      "chunk_id": null,
      "quote": null,
      "reason": "This is a meta-epidemiological study (a systematic review of systematic reviews), not a review of a specific clinical intervention's effect; therefore, a mechanism of action is not applicable."
    },
    {
      "element_id": "prisma_2020_3_e5",
      "status": "NOT_APPLICABLE",
      "chunk_id": null,
      "quote": null,
      "reason": "This is a meta-epidemiological study, not a review of a complex intervention or delivery context; therefore, a logic model is not applicable."
    }
  ],
  "confidence": 100
}

