{
  "item_id": "PRISMA_2020_5",
  "elements": [
    {
      "element_id": "prisma_2020_5_e1",
      "status": "PRESENT",
      "chunk_id": "text_8",
      "quote": "Cochrane Reviews of interventions that applied NMA were included. We excluded protocols, withdrawn reviews, overview of reviews, and diagnostic test accuracy reviews. We excluded reviews that used indirect comparison methods (e.g. calculating the difference between results obtained from pairwise meta-analyses) rather than NMA models because indirect comparisons are made in reviews without using searchable terminology. We excluded reviews that applied NMAbut for which the main summary of findings table was based on PW-MA or single trials because we primarily aimed to explore the uptake of NMA results in clinical guidelines.",
      "reason": "The authors specify the inclusion criteria (Cochrane Reviews of interventions that applied NMA) and exclusion criteria (protocols, withdrawn reviews, overview of reviews, diagnostic test accuracy reviews, reviews using indirect comparison methods, and reviews where the main summary of findings was based on PW-MA or single trials)."
    },
    {
      "element_id": "prisma_2020_5_e2",
      "status": "PARTIAL",
      "chunk_id": "text_9",
      "quote": "The CDSR was searched for NMAs to 15 th January 2024",
      "reason": "The authors specify the search end date (15th January 2024), but do not explicitly state criteria regarding language or publication status (other than the implicit inclusion of Cochrane Reviews, which are published reports)."
    },
    {
      "element_id": "prisma_2020_5_e3",
      "status": "NOT_APPLICABLE",
      "chunk_id": null,
      "quote": null,
      "reason": "This is a meta-epidemiological study (review of reviews), not a systematic review of primary studies where outcome reporting bias is typically assessed in this manner."
    },
    {
      "element_id": "prisma_2020_5_e4",
      "status": "PRESENT",
      "chunk_id": "text_13",
      "quote": "Wematched each included NMA to a PW-MA published by the same Cochrane Review Group, and with the closest publication date to the NMA (but with no more than a one-month difference between the publication dates of the NMA and PW-MA).",
      "reason": "The authors specify how they grouped studies (matching NMA reviews to PW-MA reviews) for the synthesis/comparison."
    },
    {
      "element_id": "prisma_2020_5_e5",
      "status": "PRESENT",
      "chunk_id": "text_8",
      "quote": "We excluded reviews that used indirect comparison methods (e.g. calculating the difference between results obtained from pairwise meta-analyses) rather than NMA models because indirect comparisons are made in reviews without using searchable terminology. We excluded reviews that applied NMAbut for which the main summary of findings table was based on PW-MA or single trials because we primarily aimed to explore the uptake of NMA results in clinical guidelines.",
      "reason": "The authors provide rationales for specific exclusions, such as excluding indirect comparison methods due to lack of searchable terminology and excluding reviews where the main summary of findings was based on PW-MA or single trials because the aim was to explore the uptake of NMA results."
    }
  ],
  "confidence": 95
}

